-- Legal Metrology: LM02 split in four (LM02/LM08/LM09/LM10), LM03 split in two (LM03/LM11).
update public.hub_chk_points set q='Does every pack show the maker''s name and address, product name and country of origin?', why='The most common reason for fines and Amazon listing removal.', evidence='Label checklist per product', updated_at=now() where code='LM02';
update public.hub_chk_points set q='Is net quantity checked during packing?', why='Short weight is a criminal offence.', evidence='Packing check records', updated_at=now() where code='LM03';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LM08','Legal Metrology','Does every pack show the net quantity and the month / year of packing?','A missing quantity or date is fined per pack type.','LMPC Rules 2011 r.6','lmpc',array['lm']::text[],'H','Label checklist per product',9008,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LM09','Legal Metrology','Does every pack show the MRP, including all taxes?','A wrong MRP is the most common reason for fines and Amazon listing removal.','LMPC Rules 2011 r.6','lmpc',array['lm']::text[],'H','Label checklist per product',9009,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LM10','Legal Metrology','Does every pack show a customer-care contact?','A missing customer-care contact is a labelling offence.','LMPC Rules 2011 r.6','lmpc',array['lm']::text[],'M','Label checklist per product',9010,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LM11','Legal Metrology','Is net quantity within the allowed tolerance?','Short weight is a criminal offence.','LMPC Rules 2011, First Schedule','lmpc',array['lm']::text[],'M','Fill check records',9011,true,null) on conflict (code) do nothing;
